const b = ($input.first().json.body) || {};
const s = (v) => (typeof v === 'string' ? v.trim() : '');
// Abuse guard (speed bumps for naive bots; the real fix is Turnstile / a WAF).
// 1) The browser always sends Origin; direct scripts usually do not.
// 2) The form sends how long it was open (elapsedMs); bots post instantly.
// Either failing returns the same silent "ok" as the honeypot and stores nothing.
// Add your custom domain to ORIGIN_OK when you have one.
const ORIGIN_OK = /^(http:\/\/localhost:3000|https:\/\/velure-medspa[a-z0-9-]*\.vercel\.app)$/;
const origin = String((($input.first().json.headers) || {}).origin || '');
if (!ORIGIN_OK.test(origin) || !(Number(b.elapsedMs) >= 2500)) return [{ json: { honeypot: true, valid: false } }];

if (s(b.company)) return [{ json: { honeypot: true, valid: false } }];
const errors = {};
const name = s(b.name).slice(0, 80);
const email = s(b.email).toLowerCase();
const phone = s(b.phone).slice(0, 20);
const message = s(b.message).slice(0, 1000);
if (!name) errors.name = 'Required';
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.email = 'Please enter a valid email';
if (message.length < 10) errors.message = 'Please write a few more words';
if (Object.keys(errors).length) return [{ json: { honeypot: false, valid: false, errors } }];
return [{ json: { honeypot: false, valid: true, data: { name, firstName: name.split(' ')[0], email, phone, message } } }];

// Shared Velure email shell (inline styles only — email clients ignore <style> blocks)
const shell = (title, bodyHtml) => `<!doctype html><html><body style="margin:0;padding:0;background:#FAF6F1;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FAF6F1;padding:40px 16px;">
<tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border:1px solid #EFE6DA;border-radius:14px;">
<tr><td style="padding:40px 40px 8px 40px;font-family:Georgia,'Times New Roman',serif;font-size:26px;letter-spacing:-0.5px;color:#2B2420;">Velure</td></tr>
<tr><td style="padding:0 40px;font-family:Helvetica,Arial,sans-serif;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#B08968;">Med Spa &middot; Scottsdale</td></tr>
<tr><td style="padding:28px 40px 0 40px;"><div style="height:1px;background:#EFE6DA;line-height:1px;">&nbsp;</div></td></tr>
<tr><td style="padding:28px 40px 0 40px;font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:1.25;color:#2B2420;">${title}</td></tr>
<tr><td style="padding:16px 40px 36px 40px;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4A3F39;">${bodyHtml}</td></tr>
</table>
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">
<tr><td style="padding:20px 8px;font-family:Helvetica,Arial,sans-serif;font-size:11px;line-height:1.6;color:#8A7D74;text-align:center;">
Velure Med Spa &middot; 1200 Desert Bloom Ave, Scottsdale, AZ &middot; (480) 555-0142<br>
Velure is a fictional brand created as a demonstration project by <a href="https://thaus.co" style="color:#8A7D74;">Thaus</a>.
</td></tr></table>
</td></tr></table></body></html>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (k, v) => `<tr><td style="padding:6px 0;color:#8A7D74;width:120px;vertical-align:top;">${k}</td><td style="padding:6px 0;color:#2B2420;">${v}</td></tr>`;

const d = $('Validate Contact').first().json.data;
const clientHtml = shell(
  `Thank you, ${esc(d.firstName)}.`,
  `<p style="margin:0 0 14px 0;">Your message has reached us. A member of our team will reply within one business day.</p>
   <p style="margin:0 0 6px 0;color:#8A7D74;font-size:13px;">Your message</p>
   <p style="margin:0 0 22px 0;padding:14px 16px;background:#FAF6F1;border-radius:8px;white-space:pre-line;">${esc(d.message)}</p>
   <p style="margin:0;">In the meantime, you are welcome to <a href="https://velure-medspa.vercel.app/#treatments" style="color:#B08968;">explore our treatments</a> or book a consultation online.</p>
   <p style="margin:22px 0 0 0;color:#2B2420;">With care,<br>The Velure team</p>`
);
const ownerHtml = shell('New enquiry',
  `<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;font-size:14px;">
   ${row('Name', esc(d.name))}${row('Email', esc(d.email))}${row('Phone', esc(d.phone) || '—')}
   </table>
   <p style="margin:18px 0 0 0;padding:14px 16px;background:#FAF6F1;border-radius:8px;white-space:pre-line;">${esc(d.message)}</p>`);
return [{ json: { ...d, clientHtml, ownerHtml,
  clientSubject: 'We received your message — Velure Med Spa',
  ownerSubject: `[Velure] New enquiry — ${d.name}` } }];
